import datetime,hashlib,json,pathlib,subprocess,time
root=pathlib.Path('/data/user/shuang886/PPC_RCSB_single_union/20261105/structure_source_catalog/parallel_transfer_v1')
plan=json.loads((root/"attempt.json").read_text())
assert not list(root.glob("shard_*_launch.json"))
for row in plan["manifests"]:
    assert hashlib.sha256(pathlib.Path(row["path"]).read_bytes()).hexdigest()==row["sha256"]
active={};records=[]
for i,cmd in enumerate(plan["commands"]):
    handle=(root/("shard_"+str(i)+".log")).open("a")
    p=subprocess.Popen(cmd,stdout=handle,stderr=subprocess.STDOUT)
    active[i]=(p,handle,time.monotonic())
    record={"UTC":datetime.datetime.now(datetime.timezone.utc).isoformat(),"shard":i,"pid":p.pid,"command":cmd}
    (root/("shard_"+str(i)+"_launch.json")).write_text(json.dumps(record,indent=2)+chr(10))
while active:
    for i,(p,handle,start)in list(active.items()):
        code=p.poll()
        if code is None:continue
        handle.close()
        row={"UTC":datetime.datetime.now(datetime.timezone.utc).isoformat(),"shard":i,"pid":p.pid,"returncode":code,"seconds":time.monotonic()-start,"transport_only":True,"CIF_content_accepted":False}
        (root/("shard_"+str(i)+"_completed.json")).write_text(json.dumps(row,indent=2)+chr(10))
        records.append(row);del active[i]
    if active:time.sleep(5)
result={"UTC":datetime.datetime.now(datetime.timezone.utc).isoformat(),"all_transports_exit0":all(x["returncode"]==0 for x in records),"shards":sorted(records,key=lambda x:x["shard"]),"CIF_content_accepted":False}
(root/"completed.json").write_text(json.dumps(result,indent=2)+chr(10))
raise SystemExit(0 if result["all_transports_exit0"]else 2)
